import React, { useState } from 'react';
import './App.css';

export default function App() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');

  const [touchedName, setTouchedName] = useState(false);
  const [touchedEmail, setTouchedEmail] = useState(false);
  const [touchedMessage, setTouchedMessage] = useState(false);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const nameIsValid = name.trim().length > 0;
  const emailIsValid = /\S+@\S+\.\S+/.test(email);
  const messageIsValid = message.trim().length >= 10;
  const formIsValid = nameIsValid && emailIsValid && messageIsValid;

  const handleSubmit = async (event: any) => {
    event.preventDefault();

    setTouchedName(true);
    setTouchedEmail(true);
    setTouchedMessage(true);

    setSuccessMessage('');
    setErrorMessage('');

    if (!formIsValid) {
      return;
    }

    setIsSubmitting(true);

    try {
      // This sandbox disables network APIs like fetch; fall back to a fake request.
      if (typeof fetch === 'function') {
        const response = await fetch('https://jsonplaceholder.typicode.com/posts', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ name, email, message })
        });

        if (!response.ok) {
          throw new Error('Request failed');
        }
      } else {
        await new Promise((resolve) => setTimeout(resolve, 600));
      }

      setSuccessMessage('Your message has been sent. Thank you!');
      setName('');
      setEmail('');
      setMessage('');
      setTouchedName(false);
      setTouchedEmail(false);
      setTouchedMessage(false);
    } catch (err) {
      setErrorMessage('Something went wrong. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <main className="main">
      <section className="section">
        <h1>Contact Us (Solution)</h1>

        <form className="panel" noValidate onSubmit={handleSubmit}>
          <div className="field">
            <label htmlFor="name">Name</label>
            <input
              id="name"
              type="text"
              value={name}
              onChange={(event) => setName(event.target.value)}
              onBlur={() => setTouchedName(true)}
            />
            {touchedName && !nameIsValid && (
              <p className="error">Name is required.</p>
            )}
          </div>

          <div className="field">
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              onBlur={() => setTouchedEmail(true)}
            />
            {touchedEmail && !email && (
              <p className="error">Email is required.</p>
            )}
            {touchedEmail && email && !emailIsValid && (
              <p className="error">Enter a valid email address.</p>
            )}
          </div>

          <div className="field">
            <label htmlFor="message">Message</label>
            <textarea
              id="message"
              rows={4}
              value={message}
              onChange={(event) => setMessage(event.target.value)}
              onBlur={() => setTouchedMessage(true)}
            />
            {touchedMessage && !message && (
              <p className="error">Message is required.</p>
            )}
            {touchedMessage && message && !messageIsValid && (
              <p className="error">Message should be at least 10 characters.</p>
            )}
          </div>

          <button
            type="submit"
            className="primary"
            disabled={!formIsValid || isSubmitting}
          >
            {isSubmitting ? 'Sending…' : 'Send message'}
          </button>

          {successMessage && <p className="success">{successMessage}</p>}
          {errorMessage && <p className="error">{errorMessage}</p>}
        </form>
      </section>
    </main>
  );
}

